// 把一个来源的原始报文归一成下游消费的 9 个字段。
// 当前来源的配置来自 Loop_Sources：batchSize=1，每轮只有一个源在飞，取值无歧义。
const source = $('Loop_Sources').first().json;
const items = $input.all();

const rawConfig = source.extra_config;
const config =
  typeof rawConfig === 'string' ? JSON.parse(rawConfig || '{}') : rawConfig || {};
const filters = config.filters || {};

const identity = {
  source_key: source.source_key ?? null,
  source_name: source.source_name ?? null,
  source_platform: source.source_platform ?? null,
  signal_origin: source.signal_origin ?? null,
};

// 取数失败不能伪装成文章：发一条无 url 的标记条目，由 Check_Feed_Item 拦下并告警。
function fetchFailed(reason) {
  return [{
    json: {
      ...identity,
      title: null,
      url: null,
      points: 0,
      id: null,
      created_at: new Date().toISOString(),
      fetch_error: `[${identity.source_key}] ${reason}`,
    },
  }];
}

function createdAt(raw) {
  const parsed = Date.parse(raw.pubDate || raw.isoDate || raw.date);
  return new Date(Math.min(parsed || Date.now(), Date.now())).toISOString();
}

const errorItem = items.find(
  (i) => i.json && i.json.error !== undefined && i.json.title === undefined,
);
if (errorItem) return fetchFailed(`fetch failed: ${String(errorItem.json.error)}`);
if (!items.length) return fetchFailed('fetch returned no items');

// ---- 归一 ----
let rows;
if (source.fetch_type === 'api') {
  const hits = items.flatMap((i) => (Array.isArray(i.json?.hits) ? i.json.hits : []));
  if (!hits.length) return fetchFailed('api response contained no hits');
  rows = hits.map((h) => ({
    raw: h,
    title: h.title ?? null,
    url: h.url || (h.objectID ? `https://news.ycombinator.com/item?id=${h.objectID}` : null),
    points: Number(h.points) || 0,
    comments: Number(h.num_comments) || 0,
    id: h.objectID ?? null,
  }));
} else {
  // rss-parser 把 RSS 2.0 和 Atom 都归到 title / link / pubDate|isoDate / guid|id
  rows = items.map((i) => {
    const j = i.json || {};
    return {
      raw: j,
      title: j.title ?? null,
      url: j.link ?? null,
      points: 0,
      comments: 0,
      id: j.guid ?? j.id ?? null,
    };
  });
}

// ---- 过滤：全部由 extra_config.filters 驱动，缺省即不约束 ----
if (filters.min_points != null) {
  rows = rows.filter((r) => r.points >= filters.min_points);
}
if (filters.min_comments != null) {
  rows = rows.filter((r) => r.comments >= filters.min_comments);
}

const strong = (filters.strong_keywords || []).map((k) => String(k).toLowerCase());
const blocked = (filters.hard_block_keywords || []).map((k) => String(k).toLowerCase());

if (strong.length || blocked.length || filters.max_age_hours != null || filters.max_items != null) {
  const cutoff =
    filters.max_age_hours != null
      ? Date.now() - filters.max_age_hours * 60 * 60 * 1000
      : null;
  const minScore = filters.min_score != null ? filters.min_score : 0;

  const hasAny = (text, keywords) => keywords.some((k) => text.includes(k));

  const scored = rows.map((r) => {
    const j = r.raw;
    const categories = Array.isArray(j.categories) ? j.categories.join(' ') : '';
    const text = [j.title, j.contentSnippet, j.content, j.link, categories]
      .filter(Boolean)
      .join(' ')
      .toLowerCase();
    const title = String(j.title || '').toLowerCase();

    let score;
    if (!text) score = -999;
    else if (hasAny(text, blocked)) score = -999;
    else {
      score = 0;
      if (hasAny(title, strong)) score += 3;
      if (hasAny(text, strong)) score += 2;
      if (/(\d+\.?\d*\s*(%|x|ms|s|qps|tps|tokens\/s|token\/s))/i.test(text)) score += 1;
      if (/(benchmark|throughput|latency|cost|production|ga|deploy|deployment)/i.test(text)) score += 1;
    }

    const rawDate = j.isoDate || j.pubDate || j.date || j.published || null;
    const ts = rawDate ? Date.parse(rawDate) : NaN;
    return { row: r, score, ts: Number.isFinite(ts) ? ts : null };
  });

  rows = scored
    .filter((x) => x.score >= minScore)
    .filter((x) => cutoff === null || x.ts === null || x.ts >= cutoff)
    .sort((a, b) => (b.score !== a.score ? b.score - a.score : (b.ts || 0) - (a.ts || 0)))
    .slice(0, filters.max_items != null ? filters.max_items : scored.length)
    .map((x) => x.row);
}

if (!rows.length) return fetchFailed('no items left after filtering');

return rows.map((r) => ({
  json: {
    ...identity,
    title: r.title,
    url: r.url,
    points: r.points,
    id: r.id,
    created_at: createdAt(r.raw),
  },
}));

