parameters.jsCode:
let newCount = 0;
let updateCount = 0;

try {
  newCount = $('Insert or update rows in a table').all().length;
} catch (e) {}

try {
  updateCount = $('Update_Points_Only').all().length;
} catch (e) {}

let msgParts = [];
if (newCount > 0) msgParts.push(`新增 ${newCount} 条`);
if (updateCount > 0) msgParts.push(`刷新 ${updateCount} 条`);

let finalMsg = "执行成功。";
if (msgParts.length > 0) {
    finalMsg += " " + msgParts.join("，") + "。";
} else {
    finalMsg += " 本轮无有效数据变更。";
}

return [{
  json: {
    message: finalMsg,
    target_url: "-", 
    event_type: "BATCH_COMPLETE",
    source: "Tech_Intelligence"
  }
}];

